package android.media;public class MediaFormat{public static final String KEY_WIDTH="width",KEY_HEIGHT="height";public final java.util.Map<String,Integer> values=new java.util.HashMap<>();public final java.util.Map<String,String> strings=new java.util.HashMap<>();public void setInteger(String k,int v){values.put(k,v);}public void setString(String k,String v){strings.put(k,v);}public String getString(String k){return strings.get(k);}public int getInteger(String k){if(!values.containsKey(k))throw new NullPointerException(k);return values.get(k);}public boolean containsKey(String k){return values.containsKey(k)||strings.containsKey(k);}}
